// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(uint256 _amt) internal {
        _amt = bound(_amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_amt > 0 && _amt < c.MinDeposit());
        bool _pre = c.balances(address(this)) == 0;
        try c.Deposit{value: _amt}() {} catch { return; }
        assertTrue(c.balances(address(this)) == 0);
    }

    function testFuzz_run(uint256 _amt) public {
        _run(_amt);
    }

    receive() external payable {}
}
